// Every number that tunes the bots lives in CONFIG (starting weights from patterns.md). The plan
// carries it as `config`, so the later nodes read their numbers from here too.
const CONFIG = {
  // Only the public dev API (ADR 14): on staging or prod the bots would take real guests' tables.
  apiBaseUrl: 'https://backend-showcase-dev.duckdns.org/api/v1',
  timeZone: 'Asia/Tbilisi',
  // Which bots play which visitor. Favourites come from a stable hash of the bot number.
  personas: [
    {
      name: 'regular',
      firstBot: 1,
      lastBot: 10,
      shareOfRuns: 0.5,
      favouriteLocationShare: 0.8,
      favouriteDishes: 2,
    },
    {
      name: 'occasional',
      firstBot: 11,
      lastBot: 40,
      shareOfRuns: 0.5,
      favouriteLocationShare: 0,
      favouriteDishes: 0,
    },
  ],
  // Share of runs that cancel one of the bot's own bookings instead of booking.
  cancelShare: 0.15,
  // Chance that a run first pre-orders for one of the bot's approved large bookings.
  approvedPreorderChance: 0.5,
  // Days ahead of today in restaurant time. A group's share spreads evenly over its days, then
  // every day is weighted by dayWeights, so Friday and Saturday fill up more.
  leadTime: [
    { firstDay: 0, lastDay: 0, share: 0.35 },
    { firstDay: 1, lastDay: 1, share: 0.25 },
    { firstDay: 2, lastDay: 3, share: 0.2 },
    { firstDay: 4, lastDay: 14, share: 0.2 },
  ],
  dayWeights: { Mon: 1, Tue: 1, Wed: 1, Thu: 1, Fri: 1.5, Sat: 1.5, Sun: 1.2 },
  // Weight of every start on the booking grid: lunch and dinner peaks, low hours around them.
  startWeights: {
    '10:00': 1,
    '10:30': 1,
    '11:00': 1,
    '11:30': 1,
    '12:00': 2,
    '12:30': 4,
    '13:00': 4,
    '13:30': 4,
    '14:00': 4,
    '14:30': 4,
    '15:00': 1,
    '15:30': 1,
    '16:00': 1,
    '16:30': 1,
    '17:00': 1,
    '17:30': 1,
    '18:00': 2,
    '18:30': 5,
    '19:00': 5,
    '19:30': 5,
    '20:00': 5,
    '20:30': 5,
    '21:00': 5,
    '21:30': 1,
  },
  // Party size shares by the booking date: a holiday wins over the day of the week.
  weekendDays: ['Fri', 'Sat', 'Sun'],
  partySizes: {
    weekday: { 1: 0.15, 2: 0.48, 3: 0.2, 4: 0.15, request: 0.02 },
    weekend: { 1: 0.05, 2: 0.35, 3: 0.22, 4: 0.28, request: 0.1 },
    holidays: {
      '02-14': { 1: 0, 2: 0.9, 3: 0.04, 4: 0.04, request: 0.02 },
      '03-08': { 1: 0.05, 2: 0.3, 3: 0.25, 4: 0.25, request: 0.15 },
      '12-31': { 1: 0, 2: 0.1, 3: 0.1, 4: 0.3, request: 0.5 },
    },
  },
  // How a large-party request splits into 5 to 8 people.
  requestPartySizes: { 5: 0.3, 6: 0.3, 7: 0.2, 8: 0.2 },
  // A party up to this size books at once; a larger one sends a request.
  maxInstantPartySize: 4,
  // An instant booking leaves real guests a choice: at least this many fitting tables free at
  // one location and one start (ADR 14). Requests hold no table and skip the rule.
  minFreeTables: 4,
  // The API refuses requests that start within this lead (the auto-reject lead).
  requestLeadMinutes: 120,
  // The API closes cancelling and pre-ordering this close to the start.
  cancelLeadMinutes: 30,
  preorderLeadMinutes: 30,
  preorder: {
    // Chance per person to order one dish of the category; quantities add up per dish.
    perPerson: { MAIN_COURSE: 0.9, APPETIZER: 0.5, DESSERT: 0.4 },
    // Meals by start time, each overriding some of the chances above.
    meals: [
      { name: 'lunch', firstStart: '12:00', lastStart: '14:30', perPerson: { DESSERT: 0.25 } },
      { name: 'dinner', firstStart: '18:00', lastStart: '21:30', perPerson: { APPETIZER: 0.6 } },
    ],
    // Dish weights: each location boosts its top dishes, each regular their favourites.
    dishWeight: 1,
    locationTopDishes: 3,
    locationDishWeight: 3,
    favouriteDishWeight: 3,
  },
};

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const DAY_MS = 24 * 60 * 60 * 1000;
const MINUTE_MS = 60 * 1000;

const pickWeighted = (entries) => {
  const total = entries.reduce((sum, [, weight]) => sum + weight, 0);
  let roll = Math.random() * total;
  for (const [value, weight] of entries) {
    roll -= weight;
    if (roll < 0) {
      return value;
    }
  }
  return entries.findLast(([, weight]) => weight > 0)[0];
};
const restaurantDate = (ms) =>
  new Intl.DateTimeFormat('en-CA', { timeZone: CONFIG.timeZone }).format(new Date(ms));
const addDays = (date, days) =>
  new Date(Date.parse(`${date}T00:00:00Z`) + days * DAY_MS).toISOString().slice(0, 10);
const dayName = (date) => DAY_NAMES[new Date(`${date}T00:00:00Z`).getUTCDay()];
const zoneClock = new Intl.DateTimeFormat('en-US', {
  timeZone: CONFIG.timeZone,
  hourCycle: 'h23',
  year: 'numeric',
  month: 'numeric',
  day: 'numeric',
  hour: 'numeric',
  minute: 'numeric',
  second: 'numeric',
});
// The instant of a wall-clock time on a date in the restaurant's zone.
const startInstant = (date, time) => {
  const naive = Date.parse(`${date}T${time}:00Z`);
  const parts = Object.fromEntries(
    zoneClock.formatToParts(new Date(naive)).map(({ type, value }) => [type, Number(value)]),
  );
  const zoned = Date.UTC(
    parts.year,
    parts.month - 1,
    parts.day,
    parts.hour,
    parts.minute,
    parts.second,
  );
  return naive - (zoned - naive);
};
const partyTable = (date) =>
  CONFIG.partySizes.holidays[date.slice(5)] ??
  (CONFIG.weekendDays.includes(dayName(date))
    ? CONFIG.partySizes.weekend
    : CONFIG.partySizes.weekday);

const now = Date.now();
const today = restaurantDate(now);
const persona = pickWeighted(CONFIG.personas.map((entry) => [entry, entry.shareOfRuns]));
const botNumber =
  persona.firstBot + Math.floor(Math.random() * (persona.lastBot - persona.firstBot + 1));
const date = pickWeighted(
  CONFIG.leadTime.flatMap(({ firstDay, lastDay, share }) => {
    const dayCount = lastDay - firstDay + 1;
    return Array.from({ length: dayCount }, (_, index) => {
      const day = addDays(today, firstDay + index);
      return [day, (share / dayCount) * CONFIG.dayWeights[dayName(day)]];
    });
  }),
);
const sizeGroup = pickWeighted(Object.entries(partyTable(date)));
const partySize = Number(
  sizeGroup === 'request'
    ? pickWeighted(Object.entries(CONFIG.requestPartySizes))
    : sizeGroup,
);
const notBefore =
  partySize > CONFIG.maxInstantPartySize ? now + CONFIG.requestLeadMinutes * MINUTE_MS : now;
// One random key per start that is still possible, u^(1/weight): the free start with the highest
// key is a weighted random pick among whichever starts turn out free.
const startKeys = Object.fromEntries(
  Object.entries(CONFIG.startWeights)
    .filter(([time, weight]) => weight > 0 && startInstant(date, time) > notBefore)
    .map(([time, weight]) => [time, Math.random() ** (1 / weight)]),
);

return [
  {
    json: {
      apiBaseUrl: CONFIG.apiBaseUrl,
      botNumber,
      email: `booking-bot-${botNumber}@example.com`,
      persona,
      action: Math.random() < CONFIG.cancelShare ? 'cancel' : 'book',
      preorderApproved: Math.random() < CONFIG.approvedPreorderChance,
      date,
      partySize,
      startKeys,
      config: CONFIG,
    },
  },
];

const plan = $('Plan the visit').first().json;
const setCookie = [].concat($input.first().json.headers['set-cookie'] ?? []);
const cookie = setCookie.map((header) => header.split(';')[0]).join('; ');

return [{ json: { ...plan, cookie } }];

const session = $('Keep the session').first().json;
const menu = $input.first().json;
if (menu.total > menu.items.length) {
  throw new Error(
    `The menu has ${menu.total} dishes but one page holds ${menu.items.length}: page through it`,
  );
}

return [
  {
    json: { ...session, bookings: $('List my bookings').first().json.body, dishes: menu.items },
  },
];

// With approvedPreorderChance, lists the bot's approved requests that are still open for a
// pre-order: its own confirmed bookings above the instant party size, more than the pre-order
// lead ahead. The next nodes keep the ones without a submitted part or a draft.
const visit = $input.first().json;
const { config } = visit;
const preorderOpenUntil = Date.now() + config.preorderLeadMinutes * 60 * 1000;
const candidates = visit.preorderApproved
  ? visit.bookings
      .filter(
        (booking) =>
          booking.role === 'OWNER' &&
          booking.status === 'CONFIRMED' &&
          booking.party_size > config.maxInstantPartySize &&
          Date.parse(booking.starts_at) > preorderOpenUntil,
      )
      .map((booking) => ({
        apiBaseUrl: visit.apiBaseUrl,
        cookie: visit.cookie,
        bookingId: booking.id,
        partySize: booking.party_size,
        startsAt: booking.starts_at,
        locationId: booking.location.id,
      }))
  : [];

return [{ json: { candidates } }];

// One answer per request, in the order the requests were read.
const requests = $('Check approved requests').all();

return $input.all().map((answer, index) => ({
  json: { ...requests[index].json, submittedParts: answer.json.parts.length },
}));

// Keeps the requests with no submitted part and an empty draft (a draft left by a broken run is
// never mixed into a new pre-order) and picks one. Always one item, so the run goes on to the
// action either way.
const requests = $('Note the parts').all();
const open = $input
  .all()
  .map((cart, index) => [cart.json, requests[index].json])
  .filter(([cart, request]) => request.submittedParts === 0 && cart.items.length === 0)
  .map(([, request]) => request);
const choice = open.length > 0 ? open[Math.floor(Math.random() * open.length)] : {};

return [{ json: { ...choice, next: 'action' } }];

// Orders for every person of the party by the chances of CONFIG.preorder, adjusted for lunch or
// dinner by the start time. Dishes are weighted: the location's top dishes and a regular's
// favourites come first, both ranked by a stable hash, so no state is kept between runs. Without
// a booking to order for (no open approved request) the order is empty.
const target = $input.first().json;
const visit = $('Gather the visit').first().json;
const order = {
  apiBaseUrl: target.apiBaseUrl,
  cookie: target.cookie,
  bookingId: target.bookingId,
  next: target.next,
};
if (!target.bookingId) {
  return [{ json: { ...order, lines: [] } }];
}
const { preorder, timeZone } = visit.config;
const stableHash = (text) => {
  let hash = 0x811c9dc5;
  for (const char of text) {
    hash = Math.imul(hash ^ char.codePointAt(0), 0x01000193) >>> 0;
  }
  return hash;
};
const rankByHash = (seed, ids) =>
  [...ids].sort((a, b) => stableHash(`${seed}|${a}`) - stableHash(`${seed}|${b}`));
const pickWeighted = (entries) => {
  const total = entries.reduce((sum, [, weight]) => sum + weight, 0);
  let roll = Math.random() * total;
  for (const [value, weight] of entries) {
    roll -= weight;
    if (roll < 0) {
      return value;
    }
  }
  return entries.at(-1)[0];
};

const startTime = new Intl.DateTimeFormat('en-GB', {
  timeZone,
  hourCycle: 'h23',
  hour: '2-digit',
  minute: '2-digit',
}).format(new Date(target.startsAt));
const meal = preorder.meals.find(
  ({ firstStart, lastStart }) => firstStart <= startTime && startTime <= lastStart,
);
const perPerson = { ...preorder.perPerson, ...meal?.perPerson };
const dishIds = visit.dishes.map((dish) => dish.id);
const locationTop = new Set(
  rankByHash(`location-${target.locationId}`, dishIds).slice(0, preorder.locationTopDishes),
);
const favourites = new Set(
  rankByHash(`bot-${visit.botNumber}`, dishIds).slice(0, visit.persona.favouriteDishes),
);
const dishWeight = (dish) =>
  preorder.dishWeight *
  (locationTop.has(dish.id) ? preorder.locationDishWeight : 1) *
  (favourites.has(dish.id) ? preorder.favouriteDishWeight : 1);

const quantities = new Map();
for (let person = 0; person < target.partySize; person += 1) {
  for (const [category, chance] of Object.entries(perPerson)) {
    const available = visit.dishes.filter(
      (dish) => dish.category === category && dish.is_available,
    );
    if (available.length === 0 || Math.random() >= chance) {
      continue;
    }
    const dish = pickWeighted(available.map((entry) => [entry, dishWeight(entry)]));
    quantities.set(dish.id, (quantities.get(dish.id) ?? 0) + 1);
  }
}

return [
  {
    json: {
      ...order,
      lines: [...quantities].map(([dishId, quantity]) => ({ dishId, quantity })),
    },
  },
];

const order = $input.first().json;

return order.lines.map(({ dishId, quantity }) => ({
  json: {
    apiBaseUrl: order.apiBaseUrl,
    cookie: order.cookie,
    bookingId: order.bookingId,
    dishId,
    quantity,
  },
}));

// A 409 skips that dish (sold out meanwhile, or the pre-order closed); the rest still goes in.
const answers = $input.all().map((item) => item.json);
const unexpected = answers.find(({ statusCode }) => ![200, 409].includes(statusCode));
if (unexpected) {
  throw new Error(
    `Adding a dish answered ${unexpected.statusCode}: ${JSON.stringify(unexpected.body)}`,
  );
}
const { apiBaseUrl, cookie, bookingId, next } = $('Compose the pre-order').first().json;
const added = answers.filter(({ statusCode }) => statusCode === 200).length;

return [{ json: { apiBaseUrl, cookie, bookingId, next, added } }];

// 409 ends the pre-order quietly: it closed meanwhile or a dish sold out.
const { statusCode, body } = $input.first().json;
if (![200, 409].includes(statusCode)) {
  throw new Error(`Submitting the pre-order answered ${statusCode}: ${JSON.stringify(body)}`);
}

return [{ json: { next: $('Check the dishes').first().json.next } }];

// After the approved request's pre-order the run goes on to cancel or book; after a new
// booking's pre-order it ends.
return $input.first().json.next === 'action' ? [{ json: {} }] : [];

const visit = $('Gather the visit').first().json;
if (visit.action !== 'cancel') {
  return [];
}
const cancelOpenUntil = Date.now() + visit.config.cancelLeadMinutes * 60 * 1000;
const cancellable = visit.bookings.filter(
  (booking) =>
    booking.role === 'OWNER' &&
    ['CONFIRMED', 'PENDING'].includes(booking.status) &&
    Date.parse(booking.starts_at) > cancelOpenUntil,
);
if (cancellable.length === 0) {
  return [];
}
const choice = cancellable[Math.floor(Math.random() * cancellable.length)];

return [{ json: { apiBaseUrl: visit.apiBaseUrl, cookie: visit.cookie, bookingId: choice.id } }];

// 409 is a lost race: the booking was cancelled or reached the cutoff meanwhile.
const { statusCode, body } = $input.first().json;
if (![200, 409].includes(statusCode)) {
  throw new Error(`Cancel answered ${statusCode}: ${JSON.stringify(body)}`);
}

return $input.all();

// No start left to try, e.g. today after the last start or within the request lead.
const visit = $('Gather the visit').first().json;

return visit.action === 'book' && Object.keys(visit.startKeys).length > 0 ? [{ json: visit }] : [];

// A regular books at a favourite location most of the time and elsewhere otherwise; an occasional
// visitor anywhere. The favourite is the location ranked first by a stable hash of the bot number.
const visit = $('Book this time?').first().json;
const stableHash = (text) => {
  let hash = 0x811c9dc5;
  for (const char of text) {
    hash = Math.imul(hash ^ char.codePointAt(0), 0x01000193) >>> 0;
  }
  return hash;
};
const rankByHash = (seed, ids) =>
  [...ids].sort((a, b) => stableHash(`${seed}|${a}`) - stableHash(`${seed}|${b}`));
const pick = (list) => list[Math.floor(Math.random() * list.length)];

const locationIds = $input.first().json.body.map((location) => location.id);
const chooseLocation = () => {
  const { favouriteLocationShare } = visit.persona;
  if (favouriteLocationShare === 0) {
    return pick(locationIds);
  }
  const [favourite, ...others] = rankByHash(`bot-${visit.botNumber}`, locationIds);
  return others.length === 0 || Math.random() < favouriteLocationShare ? favourite : pick(others);
};

return [{ json: { ...visit, locationId: chooseLocation() } }];

// Takes the free start with the highest plan key, a weighted pick by the start weights. An instant
// booking needs at least minFreeTables fitting tables free at that start; a request one.
const visit = $('Choose the location').first().json;
const { config } = visit;
const minFreeTables = visit.partySize > config.maxInstantPartySize ? 1 : config.minFreeTables;
const startTime = new Intl.DateTimeFormat('en-GB', {
  timeZone: config.timeZone,
  hourCycle: 'h23',
  hour: '2-digit',
  minute: '2-digit',
});
const pick = (list) => list[Math.floor(Math.random() * list.length)];

const freeTablesByStart = new Map();
for (const table of $input.first().json.items) {
  for (const slot of table.slots.filter((slot) => slot.available)) {
    const time = startTime.format(new Date(slot.starts_at));
    if (!(time in visit.startKeys)) {
      continue;
    }
    const entry = freeTablesByStart.get(time) ?? { time, startsAt: slot.starts_at, tableIds: [] };
    entry.tableIds.push(table.id);
    freeTablesByStart.set(time, entry);
  }
}
const candidates = [...freeTablesByStart.values()].filter(
  (entry) => entry.tableIds.length >= minFreeTables,
);
if (candidates.length === 0) {
  return [];
}
const start = candidates.reduce((best, entry) =>
  visit.startKeys[entry.time] > visit.startKeys[best.time] ? entry : best,
);

return [{ json: { ...visit, tableId: pick(start.tableIds), startsAt: start.startsAt } }];

// 409 ends the visit quietly: the slot was taken meanwhile, the bot already holds an overlapping
// booking or request, or a request came too close to its start. A confirmed booking far enough
// ahead goes on to the pre-order; a pending request waits for staff.
const visit = $('Pick a free slot').first().json;
const { statusCode, body } = $input.first().json;
if (statusCode === 409) {
  return [];
}
if (statusCode !== 201) {
  throw new Error(`Booking answered ${statusCode}: ${JSON.stringify(body)}`);
}
const preorderOpenUntil = Date.now() + visit.config.preorderLeadMinutes * 60 * 1000;
if (body.status !== 'CONFIRMED' || Date.parse(body.starts_at) <= preorderOpenUntil) {
  return [];
}

return [
  {
    json: {
      apiBaseUrl: visit.apiBaseUrl,
      cookie: visit.cookie,
      bookingId: body.id,
      partySize: body.party_size,
      startsAt: body.starts_at,
      locationId: body.location.id,
      next: 'end',
    },
  },
];
